.cv-extra-section {
  margin: 14px 14px 10px 14px;
  background: #12131a;
  border: 1px solid rgba(255, 255, 255, 0.08);
  border-radius: 12px;
  padding: 13px;
}
.cv-extra-title {
  font-size: 14px;
  font-weight: 800;
  color: #38bdf8;
  margin-bottom: 10px;
  display: flex;
  align-items: center;
  gap: 6px;
}
.cv-share-grid {
  display: flex;
  flex-wrap: wrap;
  justify-content: center;
  gap: 8px;
}
.cv-share-btn {
  flex: 0 0 calc(25% - 6px);
  min-width: 68px;
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  gap: 4px;
  padding: 9px 4px;
  border-radius: 10px;
  border: 1px solid rgba(255, 255, 255, 0.14);
  color: #ffffff;
  font-size: 10.5px;
  font-weight: 700;
  cursor: pointer;
  transition: transform 0.15s ease;
}
.cv-share-btn:active { transform: scale(0.95); }
.cv-sh-fb { background: linear-gradient(135deg, #1877f2, #0d5bd9); }
.cv-sh-wa { background: linear-gradient(135deg, #25d366, #128c7e); }
.cv-sh-tg { background: linear-gradient(135deg, #229ed9, #0284c7); }
.cv-sh-ms { background: linear-gradient(135deg, #00b2ff, #a855f7); }
.cv-sh-tt { background: linear-gradient(135deg, #111111, #fe2c55); }
.cv-sh-tw { background: linear-gradient(135deg, #18181b, #3f3f46); }
.cv-sh-cp { background: linear-gradient(135deg, #f59e0b, #d97706); color: #111; }
.cv-bottom-home-wrap {
  margin: 14px 14px 24px 14px;
}
.cv-bottom-home-btn {
  width: 100%;
  padding: 13px;
  border-radius: 999px;
  border: none;
  background: linear-gradient(135deg, #e11d48, #f97316);
  color: #ffffff;
  font-size: 14px;
  font-weight: 800;
  cursor: pointer;
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 8px;
  box-shadow: 0 6px 20px rgba(225, 29, 72, 0.38);
}

