(function() {
  if (window._cvWatchUnlockPatched) return;
  window._cvWatchUnlockPatched = true;

  var watchUnlockMap = {};
  var pendingWatchId = null;
  var watchAdLeftAt = 0;
  var WATCH_AD_FALLBACK = 'https://directyp.org/4/c7e78de73c1a473eadfa5b2b5477313d';

  function getWatchAdUrl() {
    if (typeof ENTRY_AD_URL !== 'undefined' && ENTRY_AD_URL && /^https?:\/\//i.test(ENTRY_AD_URL)) {
      return ENTRY_AD_URL;
    }
    return WATCH_AD_FALLBACK;
  }

  function startMoviePlayerDirectly() {
    if (!currentMovie) return;
    stopHeroBgPreview();
    var pw = document.getElementById('cinePlayerWrap');
    var customUrl = (currentMovie.customWatchUrl || '').trim();
    var pSliders = document.getElementById('playerSlidersRow');
    var volBar = document.getElementById('playerVolumeBar');
    var watchBtn = document.querySelector('.btn-watch-online');
    if (watchBtn) watchBtn.innerHTML = '▶️ Watch Full Movie (আনলক সম্পন্ন ✅)';

    if (customUrl && (/^https?:\/\//i.test(customUrl) || /^www\./i.test(customUrl))) {
      document.getElementById('serverSelectionBar').style.display = 'none';
      loadCustomUrlIntoPlayer(customUrl);
      pw.style.display = 'block';
      pw.scrollIntoView({ behavior: 'smooth' });
      return;
    }

    resetPlayerElements();
    document.getElementById('serverSelectionBar').style.display = 'flex';
    if (pSliders) pSliders.style.display = 'flex';
    if (volBar) volBar.style.display = 'none';
    switchOnlineServer(1);
    pw.style.display = 'block';
    pw.scrollIntoView({ behavior: 'smooth' });
  }

  function completeWatchReturn() {
    if (!pendingWatchId || !currentMovie || currentMovie.id !== pendingWatchId) return;
    if (Date.now() - watchAdLeftAt < 1200) return;
    watchUnlockMap[currentMovie.id] = true;
    pendingWatchId = null;
    startMoviePlayerDirectly();
  }

  document.addEventListener('visibilitychange', function() {
    if (document.visibilityState === 'visible') completeWatchReturn();
  });
  window.addEventListener('focus', completeWatchReturn);

  var origOpenDetail = window.openCineDetailWithObj;
  if (typeof origOpenDetail === 'function') {
    window.openCineDetailWithObj = function(movieObj) {
      pendingWatchId = null;
      origOpenDetail(movieObj);
      var watchBtn = document.querySelector('.btn-watch-online');
      if (watchBtn && movieObj) {
        watchBtn.innerHTML = watchUnlockMap[movieObj.id]
          ? '▶️ Watch Full Movie (আনলক সম্পন্ন ✅)'
          : '▶️ Watch Full Movie (বিজ্ঞাপন দেখে দেখুন)';
      }
    };
  }

  window.playOnlineMovie = function() {
    if (!currentMovie) return;
    stopHeroBgPreview();
    var customUrl = (currentMovie.customWatchUrl || '').trim();
    if (!currentMovie.isFromSheet && !customUrl) {
      document.getElementById('nonSheetWatchModal').style.display = 'flex';
      return;
    }

    if ((typeof ADS_ENABLED !== 'undefined' && !ADS_ENABLED) || watchUnlockMap[currentMovie.id]) {
      startMoviePlayerDirectly();
      return;
    }

    pendingWatchId = currentMovie.id;
    watchAdLeftAt = Date.now();
    var watchBtn = document.querySelector('.btn-watch-online');
    if (watchBtn) watchBtn.innerHTML = '⏳ বিজ্ঞাপন ভালো করে দেখে ব্যাক আসেন...';
    openSafeUrl(getWatchAdUrl());
  };
})();

(function() {
  var nav = document.querySelector('.bottom-nav');
  if (!nav || document.getElementById('cineApkNavBtn')) return;

  var btn = document.createElement('div');
  btn.id = 'cineApkNavBtn';
  btn.className = 'nav-item';
  btn.style.color = '#22c55e';
  btn.style.fontWeight = '700';
  btn.innerHTML =
    '<span class="nav-icon">' +
      '<svg width="20" height="20" viewBox="0 0 24 24" fill="none">' +
        '<circle cx="12" cy="12" r="11" fill="#22c55e"/>' +
        '<path d="M12 6.5V14.5M12 14.5L8.5 11M12 14.5L15.5 11M7.5 17.5H16.5" stroke="#ffffff" stroke-width="2.2" stroke-linecap="round" stroke-linejoin="round"/>' +
      '</svg>' +
    '</span>' +
    '<span>App</span>';

  btn.onclick = function() {
    var apkUrl = 'https://cinevibebd.pages.dev/CineVibeBD.apk';
    if (window.Telegram && window.Telegram.WebApp && window.Telegram.WebApp.initData && window.Telegram.WebApp.openLink) {
      window.Telegram.WebApp.openLink(apkUrl);
      return;
    }
    var a = document.createElement('a');
    a.href = '/CineVibeBD.apk';
    a.download = 'CineVibeBD.apk';
    document.body.appendChild(a);
    a.click();
    a.remove();
  };

  nav.appendChild(btn);
})();
